  ('80e24a11-e356-4f41-8b5a-10c0a1000001','125d93e7-38ae-4746-a866-8c428ca4196d','e2b2bcbc-c3b0-4bee-b7d7-d2a0d1c3552b','1cor-london-pupillage-2027-recruitment','London 12-Month Pupillage — 2027 Recruitment','12-Month Pupillage — 2027 Recruitment','Two fully funded 12-month London pupillages are offered every year across chambers’ principal practice areas.','in_person','https://www.1cor.com/london/careers/pupillage/','https://www.pupillagegateway.com/',true,true,300,date '2026-10-15',date '2026-11-23',now(),now(),false),
  ('80e24a11-e356-4f41-8b5a-10c0a1000002','125d93e7-38ae-4746-a866-8c428ca4196d','e2b2bcbc-c3b0-4bee-b7d7-d2a0d1c3552b','1cor-brighton-civil-pupillage-2027-recruitment','Brighton Civil Pupillage — 2027 Recruitment','Civil Pupillage — 2027 Recruitment','One funded 12-month civil pupillage is normally offered every year in Brighton.','in_person','https://www.1cor.com/brighton/careers/pupillage/','https://www.pupillagegateway.com/',true,true,310,date '2026-10-15',date '2026-11-23',now(),now(),false),
  ('80e24a11-e356-4f41-8b5a-10c0a1000003','125d93e7-38ae-4746-a866-8c428ca4196d','e2b2bcbc-c3b0-4bee-b7d7-d2a0d1c3552b','1cor-brighton-family-pupillage-2027-recruitment','Brighton Family Pupillage — 2027 Recruitment','Family Pupillage — 2027 Recruitment','Up to two funded 12-month family pupillages are normally offered every year in Brighton.','in_person','https://www.1cor.com/brighton/careers/pupillage/','https://www.pupillagegateway.com/',true,true,320,date '2026-10-15',date '2026-11-23',now(),now(),false),
  ('80e24a11-e356-4f41-8b5a-10c0a1000004','125d93e7-38ae-4746-a866-8c428ca4196d','45e6b1b6-6589-4e4f-b6b7-7cf2ddc28a89','1cor-london-assessed-mini-pupillage-annual','London Assessed Mini-Pupillage — Annual Programme','Assessed Mini-Pupillage','Ten assessed three-day mini-pupillages are offered annually to eligible applicants from socio-economically disadvantaged backgrounds.','in_person','https://www.1cor.com/london/assessed-mini-pupillage/','https://www.1cor.com/london/assessed-mini-pupillage/',true,true,330,date '2026-10-15',date '2027-04-01',now(),now(),false);

insert into public.career_opportunity_cycles (
  id, opportunity_id, cycle_key, cycle_label, application_year, programme_year,
  application_model, opens_on, opens_at, opens_timezone, closes_on, closes_at,
  closes_timezone, programme_dates_text, application_dates_text, date_precision,
  duration_text, places_text, source_status, study_stage_text, academic_criteria,
  eligibility_text, application_process_text, assessments_text,
  progression_route_text, funding_text, expenses_text, disability_support_text,
  official_url, application_url, active, research_checked_on, created_at, updated_at,
  programme_structure_text, additional_details_text
) values
  ('90e24a11-e356-4f41-8b5a-10c0a1000001','80e24a11-e356-4f41-8b5a-10c0a1000001','1cor-london-pupillage:2027','2027 recruitment',2027,2028,'fixed_deadline',date '2027-01-04',time '11:00','Europe/London',date '2027-01-28',time '23:59','Europe/London','A fully funded 12-month pupillage.','The 2027 Pupillage Gateway submission window opens at 11:00 on 4 January and closes at 23:59 on 28 January.','exact','12 months','Two places are offered every year.','upcoming','Applicants must meet the regulatory requirements to commence pupillage.','Applicants are assessed against the published merit criteria; no minimum degree classification is stated.','Selection is based on intellectual and analytical ability, written and oral advocacy, temperament, interpersonal skills and motivation for the Bar and 1COR.','Apply through the Pupillage Gateway. Shortlisted candidates attend a first-round interview followed by a second interview for those who progress.','Application sift, first-round interview, second interview and references.','Every 12-month pupil may be considered for tenancy at a full chambers meeting, usually in late June.','Two fully funded places are offered every year. Chambers also describes an advance drawdown subject to its conditions.','Required pupillage training courses are paid by chambers.','Applicants may request reasonable adjustments; the London premises have step-free access.','https://www.1cor.com/london/careers/pupillage/','https://www.pupillagegateway.com/',true,date '2026-10-15',now(),now(),'Pupillage is divided into four supervised stages with formal reviews, written feedback and experience of written work and advocacy.','Normal working hours are described as 9am–6pm, with 20 working days of holiday during the year.'),
  ('90e24a11-e356-4f41-8b5a-10c0a1000002','80e24a11-e356-4f41-8b5a-10c0a1000002','1cor-brighton-civil-pupillage:2027','2027 recruitment',2027,2028,'fixed_deadline',date '2027-01-04',time '11:00','Europe/London',date '2027-01-28',time '23:59','Europe/London','A funded 12-month civil pupillage.','The 2027 Pupillage Gateway submission window opens at 11:00 on 4 January and closes at 23:59 on 28 January.','exact','12 months','One civil place is normally offered every year.','upcoming','Applicants must meet the regulatory requirements to commence pupillage.','Successful applicants tend to have at least a 2:1; academic achievement is considered contextually.','Applications are assessed on merit against intellectual, advocacy, temperament, interpersonal and motivation criteria.','Apply through the Pupillage Gateway. Interviews may take place in Brighton or remotely.','Contextual application assessment followed by interview.','Tenancy is considered at a full chambers meeting, normally in June or July.','The Brighton careers page states a £30,000 pupillage award.','Chambers pays specified travel costs during the non-practising period, required training courses and Ethics examination materials.','Applicants may request reasonable adjustments.','https://www.1cor.com/brighton/careers/pupillage/','https://www.pupillagegateway.com/',true,date '2026-10-15',now(),now(),'Pupillage is normally divided between two supervisors and includes written work, conferences, court observation, advocacy training and the pupil’s own court work in the practising period.','The Brighton programme normally recruits one civil pupil every year.'),
  ('90e24a11-e356-4f41-8b5a-10c0a1000003','80e24a11-e356-4f41-8b5a-10c0a1000003','1cor-brighton-family-pupillage:2027','2027 recruitment',2027,2028,'fixed_deadline',date '2027-01-04',time '11:00','Europe/London',date '2027-01-28',time '23:59','Europe/London','A funded 12-month family pupillage.','The 2027 Pupillage Gateway submission window opens at 11:00 on 4 January and closes at 23:59 on 28 January.','exact','12 months','Up to two family places are normally offered every year.','upcoming','Applicants must meet the regulatory requirements to commence pupillage.','Successful applicants tend to have at least a 2:1; academic achievement is considered contextually.','Applications are assessed on merit against intellectual, advocacy, temperament, interpersonal and motivation criteria.','Apply through the Pupillage Gateway. Interviews may take place in Brighton or remotely.','Contextual application assessment followed by interview.','Tenancy is considered at a full chambers meeting, normally in June or July.','The Brighton careers page states a £30,000 pupillage award.','Chambers pays specified travel costs during the non-practising period, required training courses and Ethics examination materials.','Applicants may request reasonable adjustments.','https://www.1cor.com/brighton/careers/pupillage/','https://www.pupillagegateway.com/',true,date '2026-10-15',now(),now(),'Pupillage is normally divided between two supervisors and includes written work, conferences, court observation, advocacy training and the pupil’s own court work in the practising period.','The Brighton programme normally recruits up to two family pupils every year.'),
  ('90e24a11-e356-4f41-8b5a-10c0a1000004','80e24a11-e356-4f41-8b5a-10c0a1000004','1cor-assessed-mini-pupillage:annual','Annual programme',null,null,'fixed_deadline',null,null,null,null,null,null,'Ten three-day assessed mini-pupillages take place during the autumn term.','The application window is announced annually on the assessed mini-pupillage page.','text_only','3 days','Ten places are offered every year.','annual','Applicants must be at least in their second year of university or be a graduate.','Applicants must demonstrate high academic achievement.','Applicants must satisfy the published state-school and socio-economic eligibility criteria.','Complete the scheme form and submit it with a current CV in accordance with the instructions on the scheme page.','Written application assessment and assessed performance during the placement.','Strong performers receive a guaranteed first-round pupillage interview after also applying through the Pupillage Gateway.','A £150 bursary is provided.','Up to a further £150 or more may be provided at chambers’ discretion for necessary travel and accommodation.','Disabled applicants are particularly encouraged to apply and may request reasonable adjustments.','https://www.1cor.com/london/assessed-mini-pupillage/','https://www.1cor.com/london/assessed-mini-pupillage/',true,date '2026-10-15',now(),now(),'Each assessed mini-pupillage lasts three days during the autumn term.','The scheme is aimed at eligible applicants from socio-economically disadvantaged backgrounds.');

