update public.chambers set
  pupillage_overview='London offers two fully funded 12-month pupillages every year. Brighton offers up to two funded family pupillages and one funded civil pupillage every year. Applications are made through the Pupillage Gateway; the 2027 submission window runs from 4 to 28 January 2027.',
  mini_pupillage_overview='London offers ten regular three-day mini-pupillages every year and a separate annual ten-place assessed mini-pupillage for eligible applicants from socio-economically disadvantaged backgrounds. Brighton offers up to ten mini-pupillages every year, generally lasting three days.',
  research_checked_on=date '2026-10-15',next_review_on=date '2026-11-23',updated_at=now()
where organisation_id='125d93e7-38ae-4746-a866-8c428ca4196d';

update public.legal_organisations set
  overview='1 Crown Office Row is a barristers’ chambers with offices in London and Brighton. It offers annual London and Brighton pupillages, separate London and Brighton mini-pupillages, and a London assessed mini-pupillage scheme for eligible applicants from socio-economically disadvantaged backgrounds.',
  research_checked_on=date '2026-10-15',next_review_on=date '2026-11-23',updated_at=now()
where id='125d93e7-38ae-4746-a866-8c428ca4196d';

